   187→impl Workout {
   188→    /// Create a new workout with the given name and segments.
   189→    pub fn new(name: String, segments: Vec<WorkoutSegment>) -> Self {
   190→        let total_duration_seconds = segments.iter().map(|s| s.duration_seconds).sum();
   191→
   192→        Self {
   193→            id: Uuid::new_v4(),
   194→            name,
   195→            description: None,
   196→            author: None,
   197→            source_file: None,
   198→            source_format: None,
   199→            segments,
   200→            total_duration_seconds,
   201→            estimated_tss: None,
   202→            estimated_if: None,
   203→            tags: Vec::new(),
   204→            created_at: Utc::now(),
   205→        }
   206→    }
