   208→    /// Calculate estimated TSS and IF for a given FTP.
   209→    pub fn calculate_estimates(&mut self, ftp: u16) {
   210→        if self.segments.is_empty() || ftp == 0 {
   211→            return;
   212→        }
   213→
   214→        // Calculate weighted average intensity
   215→        let mut total_weighted_power = 0.0f64;
   216→        let mut total_duration = 0u32;
   217→
   218→        for segment in &self.segments {
   219→            let duration = segment.duration_seconds;
   220→            let avg_power = match &segment.power_target {
   221→                PowerTarget::Absolute { watts } => *watts as f64,
   222→                PowerTarget::PercentFtp { percent } => ftp as f64 * *percent as f64 / 100.0,
   223→                PowerTarget::Range { start, end } => {
   224→                    let start_watts = start.to_watts(ftp) as f64;
   225→                    let end_watts = end.to_watts(ftp) as f64;
   226→                    (start_watts + end_watts) / 2.0
   227→                }
   228→            };
   229→
   230→            total_weighted_power += avg_power * duration as f64;
   231→            total_duration += duration;
   232→        }
   233→
   234→        if total_duration > 0 {
   235→            let avg_power = total_weighted_power / total_duration as f64;
   236→            let intensity_factor = (avg_power / ftp as f64) as f32;
   237→            let duration_hours = total_duration as f32 / 3600.0;
   238→            let tss = duration_hours * intensity_factor * intensity_factor * 100.0;
   239→
   240→            self.estimated_if = Some(intensity_factor);
   241→            self.estimated_tss = Some(tss);
   242→        }
   243→    }
   244→}
